                        compiled.push({ ...f, id: `f-${f.id}`, title: f.name, state: state.name, type: 'Festival', height: heights[hIdx++ % heights.length] });
                    }
                })
            }
        });

        // shuffle lightly or sort
        return compiled.sort(() => 0.5 - Math.random());
    }, []);

    const filteredArts = useMemo(() => {
