                            animate={{ scale: 1, opacity: 1, y: 0 }}
                            exit={{ scale: 0.96, opacity: 0, y: 12 }}
                            transition={{ type: 'spring', damping: 28, stiffness: 300 }}
                            className="bg-white/10 backdrop-blur-2xl rounded-2xl sm:rounded-3xl overflow-hidden w-full max-w-5xl max-h-[90vh] sm:max-h-[85vh] flex flex-col md:flex-row shadow-[0_24px_80px_-12px_rgba(0,0,0,0.5)] ring-1 ring-white/20 relative my-4"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="w-full md:w-1/2 min-h-[200px] sm:h-64 md:h-auto overflow-hidden relative bg-white/5 shrink-0">
                                <img
                                    src={hasImage(selectedArt.img) && !failedImageUrls.has(getImageUrl(selectedArt.img!)) ? getImageUrl(selectedArt.img!) : getFallbackImage(selectedArt.title ?? selectedArt.name, artTypeToFallbackType(selectedArt.type))}
                                    alt={selectedArt.title ?? ''}
                                    className="w-full h-full object-cover object-center opacity-90"
                                    onError={(e) => {
