                                {(placed[region] || []).map(({ state, correct }) => (
                                    <span
                                        key={state}
                                        className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-sm font-medium ${
                                            correct ? 'bg-emerald-600/90 text-white' : 'bg-red-600/90 text-white'
                                        }`}
